const parts = String(msg.topic || '').split('/').filter(Boolean);
if (parts.length < 2) return null;

// Fill this table only when MQTT device ids differ from MySQL device_code values.
const deviceMap = {
  // 'EMSB_03_EM32': 'H1_EMSB_A4_03_EM'
};

const mqttDeviceId = parts[parts.length - 2];
const mqttTopicPrefix = parts.slice(0, -2).join('/');
const deviceCode = deviceMap[mqttDeviceId] || mqttDeviceId;
const seen = flow.get('n4FuxaDiscovered') || {};

// Re-submit every 10 minutes so a restarted FUXA can self-heal.
const now = Date.now();
if (seen[mqttDeviceId] && now - seen[mqttDeviceId] < 600000) return null;
seen[mqttDeviceId] = now;
flow.set('n4FuxaDiscovered', seen);

msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
  mqttDeviceId,
  mqttTopicPrefix,
  deviceCode,
  modelCode: 'SPM32'
};
return msg;
